package net.ronm19.phantomism.client.vfx;

import java.util.*;
import net.minecraft.world.phys.Vec3;
import net.ronm19.phantomism.vfx.VoidVfx;

public final class VoidEffects {
    private VoidEffects(){}
    public static boolean supports(VfxRegistry.Form form){return form==VfxRegistry.Form.VOID||form==VfxRegistry.Form.VOID_BOLT||form==VfxRegistry.Form.VOID_AFTERIMAGE||form==VfxRegistry.Form.NULL_HORIZON;}
    public static List<VfxMesh.Batch> build(VfxEffect effect,Vec3 camera,float partial,int limit){
        var definition=effect.definition;var kind=effect.packet.effect();float age=effect.age(partial),duration=effect.packet.duration(),fade=Math.clamp(Math.min(age/5,(duration-age)/12),0,1);double progress=Math.clamp(age/duration,0,1),radius=effect.packet.radius();Vec3 center=effect.interpolated(partial);int violet=effect.packet.primary(),lavender=effect.packet.secondary(),segments=16+effect.quality*8;var mesh=new VfxMesh.Builder(camera,Math.max(0,limit),1,effect.packet.direction());
        if(definition.form()==VfxRegistry.Form.NULL_HORIZON){
            double opening=Math.clamp(age/45D,0,1),closing=Math.clamp((duration-age)/30D,0,1),extent=radius*opening*closing;Vec3 sky=center.add(0,16*opening,0);
            mesh.face(sky,Math.max(.1D,extent*.38D),-age*.004D,true,0x10051E,fade*.25F,definition.hand());mesh.ring(sky,Math.max(.1D,extent*.42D),.14D,true,-age*.007D,violet,fade*.85F,segments,definition.trail());mesh.face(sky,Math.max(.1D,extent*.48D),age*.003D,true,lavender,fade*.55F,definition.face());
            mesh.ring(center.add(0,.2D,0),Math.max(.1D,extent),.055D,true,age*.002D,violet,fade*.5F,segments,definition.trail());
            if(age>45){for(int arc=0;arc<3;arc++){double height=3+arc*4,reach=(19-arc*3)*opening*closing;mesh.ring(center.add(0,height,0),Math.max(.1D,reach),.035D,true,(arc%2==0?1:-1)*age*.004D,arc%2==0?violet:lavender,fade*.42F,segments,definition.trail());}}
            for(int fragment=0;fragment<4+effect.quality;fragment++){double angle=fragment*Math.PI*2/(4+effect.quality)+age*.004D,reach=extent*.65D;Vec3 point=center.add(Math.cos(angle)*reach,5+Math.sin(age*.02D+fragment)*2,Math.sin(angle)*reach);mesh.face(point,opening*closing*.8D,angle,false,lavender,fade*.72F,definition.ring());if(age>45){var points=new ArrayList<Vec3>();for(int sample=0;sample<=12;sample++){double fraction=sample/12D,bend=angle+fraction*1.4D;points.add(center.add(Math.cos(bend)*reach*(1-fraction),1+fraction*13,Math.sin(bend)*reach*(1-fraction)));}mesh.ribbon(points,.045D,violet,fade*.4F,definition.trail());}}
            for(int wave:new int[]{100,160,220}){double elapsed=age-wave;if(elapsed>=0&&elapsed<20){float opacity=fade*(float)(1-elapsed/20);mesh.ring(center.add(0,.5D,0),Math.max(.1D,radius*elapsed/20),.18D,true,0,lavender,opacity*.85F,segments,definition.trail());}}
        }else if(definition.form()==VfxRegistry.Form.VOID_BOLT){mesh.ribbon(effect.history(partial),.2D,violet,fade*.9F,definition.trail());mesh.ribbon(effect.history(partial),.045D,lavender,fade,definition.trail());mesh.face(center,.55D,age*.06D,false,violet,fade,definition.hand());mesh.face(center,.3D,-age*.1D,false,lavender,fade,definition.face());
        }else if(kind.equals(VoidVfx.GRASP)||kind.equals(VoidVfx.SEAL)){
            boolean grasp=kind.equals(VoidVfx.GRASP);mesh.face(center.add(0,.1D,0),1.25D,-age*.006D,true,violet,fade*.65F,definition.face());for(int tendril=0;tendril<3;tendril++){double angle=tendril*Math.PI*2/3+age*.008D;var points=new ArrayList<Vec3>();for(int sample=0;sample<=16;sample++){double fraction=sample/16D,bend=angle+fraction*Math.PI*1.5D,reach=.55D+Math.sin(fraction*Math.PI)*.5D;points.add(center.add(Math.cos(bend)*reach,fraction*2.4D,Math.sin(bend)*reach));}mesh.ribbon(points,grasp?.065D:.035D,lavender,fade*.7F,definition.trail());}mesh.face(center.add(0,2.5D,0),.55D,age*.012D,false,lavender,fade*.9F,definition.face());
        }else if(kind.equals(VoidVfx.ANCHOR)){mesh.face(center.add(0,.08D,0),1.4D,age*.002D,true,violet,fade*.5F,definition.face());mesh.face(center.add(0,1.2D+Math.sin(age*.04D)*.1D,0),.45D,age*.02D,false,lavender,fade*.8F,definition.hand());
        }else if(kind.equals(VoidVfx.SHIELD)){for(int ring=0;ring<3;ring++){mesh.ring(center.add(0,1,0),2,.035D,ring==0,age*.003D+ring*Math.PI/3,ring==1?lavender:violet,fade*.45F,segments,definition.trail());}for(int panel=0;panel<4;panel++){double angle=panel*Math.PI/2+age*.007D;mesh.face(center.add(Math.cos(angle)*1.6D,1.2D,Math.sin(angle)*1.6D),.8D,angle,false,lavender,fade*.3F,definition.ring());}
        }else if(kind.equals(VoidVfx.STEP)||kind.equals(VoidVfx.RESCUE)){
            var points=new ArrayList<Vec3>();for(int sample=0;sample<=20;sample++){double fraction=sample/20D;points.add(center.add(effect.packet.direction().scale(fraction)).add(0,.7D+Math.sin(fraction*Math.PI)*.4D,0));}mesh.ribbon(points,.2D*(1-progress),violet,fade*.8F,definition.trail());mesh.ribbon(points,.04D,lavender,fade*.9F,definition.trail());for(int echo=1;echo<=3;echo++){mesh.face(center.add(effect.packet.direction().scale(echo/4D)).add(0,.5D,0),1.2D*(1-progress),-age*.01D,false,violet,fade*.3F,definition.ring());}
        }else if(kind.equals(VoidVfx.FIELD)){mesh.face(center.add(0,.12D,0),radius*.65D,age*.001D,true,violet,fade*.18F,definition.face());for(int fragment=0;fragment<3;fragment++){double angle=fragment*Math.PI*2/3+age*.01D;mesh.face(center.add(Math.cos(angle)*2,.7D,Math.sin(angle)*2),.3D,angle,false,lavender,fade*.5F,definition.ring());}
        }else{boolean closing=kind.equals(VoidVfx.COLLAPSE);double reach=Math.max(.1D,radius*(closing?1-progress:progress));mesh.ring(center.add(0,.3D,0),reach,kind.equals(VoidVfx.PULSE)||kind.equals(VoidVfx.WAVE)?.13D:.055D,true,age*.004D,violet,fade*.75F,segments,definition.trail());if(!closing){mesh.face(center.add(0,.6D,0),Math.max(.1D,1-progress),age*.02D,false,lavender,fade*.85F,definition.hand());for(int fragment=0;fragment<4;fragment++){double angle=fragment*Math.PI/2+age*.01D;mesh.face(center.add(Math.cos(angle)*Math.min(3,reach),.5D+progress,Math.sin(angle)*Math.min(3,reach)),.2D,angle,false,lavender,fade*.7F,definition.ring());}}}
        var echoes=new ArrayList<VfxEffect.Pose>();if(kind.equals(VoidVfx.STEP)&&effect.packet.direction().lengthSqr()>.01D){for(int echo=0;echo<effect.quality;echo++){echoes.add(new VfxEffect.Pose(center.add(effect.packet.direction().scale((echo+1D)/(effect.quality+1D))),(float)Math.toDegrees(Math.atan2(-effect.packet.direction().x,effect.packet.direction().z)),0));}}return mesh.finish(echoes,fade,definition.silhouette(),violet);
    }
}
